UPDATE tb_att_lt_time_attend_plan_n tap
SET tap.progress_status_code = (SELECT status_code FROM lgcom_approval_request_n WHERE request_master_id = tap.approval_request_id AND request_code = tap.request_code)
      ,tap.last_update_user_id  = #{sessionAppUserId}
      ,tap.last_update_date     = SYSDATE
 WHERE tap.approval_request_id = #{requestMasterId}
   AND tap.request_code = #{requestCode}

		UPDATE tb_att_lt_time_attend_plan_n


           SET progress_status_code = '30'


           SET progress_status_code = '40'


           SET progress_status_code = '50'


           SET progress_status_code = '70'


           SET progress_status_code = '20'


		      ,last_update_user_id  = #{sessionAppUserId}
		      ,last_update_date     = SYSDATE
		 WHERE approval_request_id = #{requestMasterId}
		 AND request_code = #{requestCode}
		 AND subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode}
